@charset "UTF-8";
.badge-avatar-wrap {
  position: relative;
  display: inline-block;
}
.badge-avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: #07c160;
}
.badge-avatar-dot {
  position: absolute;
  top: -4px;
  right: -4px;
}

.flex-demo-item {
  background: #07c160;
  color: #fff;
  text-align: center;
  line-height: 40px;
  border-radius: 4px;
  margin: 2px;
}
.flex-demo-stack {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.flex-demo-row {
  background: #f5f5f5;
  border-radius: 4px;
  padding: 4px;
}
.flex-demo-box {
  width: 64px;
  height: 40px;
  line-height: 40px;
  text-align: center;
  background: #10aeff;
  color: #fff;
  border-radius: 4px;
  font-size: 13px;
}
.flex-demo-box-tall {
  height: 60px;
  line-height: 60px;
}
.flex-demo-tall {
  height: 80px;
  background: #f5f5f5;
  border-radius: 4px;
  padding: 4px;
}
.flex-demo-wrap {
  background: #f5f5f5;
  border-radius: 4px;
  padding: 4px;
}
.flex-demo-col {
  background: #f5f5f5;
  border-radius: 4px;
  padding: 4px;
}

.icon-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.icon-grid__item {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 88px;
  padding: 12px 4px;
  border-radius: 4px;
  cursor: pointer;
}
.icon-grid__item:hover {
  background: #f5f5f5;
}
.icon-grid__label {
  margin-top: 8px;
  font-size: 12px;
  color: #888;
  text-align: center;
}

.loading-dark-bg {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 80px;
  background: #1a1a1a;
  border-radius: 4px;
}


